-- Independent market directory; existing orders, products and migrations are unchanged.
CREATE TYPE "MarketPointKind" AS ENUM ('STALL', 'STORE', 'FOODCOURT', 'SERVICE', 'OTHER', 'ENTRY');

CREATE TABLE "MarketPoint" (
  "id" SERIAL NOT NULL,
  "slug" VARCHAR(180) NOT NULL,
  "name" VARCHAR(160) NOT NULL,
  "unitNumber" VARCHAR(40),
  "kind" "MarketPointKind" NOT NULL,
  "description" VARCHAR(3000),
  "sampleAssortment" VARCHAR(2000),
  "photoUrl" TEXT,
  "floor" INTEGER NOT NULL DEFAULT 2,
  "mapX" DOUBLE PRECISION NOT NULL,
  "mapY" DOUBLE PRECISION NOT NULL,
  "isPublished" BOOLEAN NOT NULL DEFAULT false,
  "sortOrder" INTEGER NOT NULL DEFAULT 0,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "MarketPoint_pkey" PRIMARY KEY ("id"),
  CONSTRAINT "MarketPoint_floor_check" CHECK ("floor" BETWEEN 1 AND 20),
  CONSTRAINT "MarketPoint_coordinates_check" CHECK ("mapX" BETWEEN 0 AND 100 AND "mapY" BETWEEN 0 AND 100)
);

CREATE UNIQUE INDEX "MarketPoint_slug_key" ON "MarketPoint"("slug");
CREATE INDEX "MarketPoint_floor_isPublished_sortOrder_id_idx" ON "MarketPoint"("floor", "isPublished", "sortOrder", "id");

